from pathlib import Path
import json,html,hashlib
D=Path('docs/coach/phase15');esc=html.escape
s='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>PARISFIT · Phase15</title><style>*{box-sizing:border-box}body{margin:0;background:#edf5ef;color:#173f33;font:16px/1.65 system-ui;overflow-wrap:anywhere}main{max-width:1080px;margin:auto;padding:24px}h1{font-size:clamp(28px,5vw,46px);line-height:1.15}section{background:white;padding:24px;margin:22px 0;border-radius:18px}a{color:#165e47}.tag{background:#f6d4c6;padding:8px 16px;display:inline-block;border-radius:20px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left;vertical-align:top}pre{white-space:pre-wrap;font:inherit}summary{cursor:pointer;font-weight:bold}</style><main><a href="../phase14/index.html">← Phase14 · qualification du modèle</a><p>PARISFIT / COACH RECHERCHE / PHASE15</p><h1>Récupérer les preuves.<br>Préparer la reconstruction, sans la présumer.</h1><p class="tag">Scénario B · EN ATTENTE DE DOCUMENTATION</p><section><h2>Décision</h2><p>La documentation est partielle : valeurs S01 et données disponibles, mais MarkerSet, placement, transformations et procédure de scaling/registration insuffisants. Aucune nouvelle correspondance confirmée. L'utilisation anatomique reste <b>REFUSÉE</b> en l'état.</p><p><b>IK, COP et retarget : NON TESTÉS.</b> Aucun message aux auteurs envoyé. Aucune validation professionnelle obtenue. Le scénario B de cette phase ne lève pas le refus de la phase14.</p></section><section><h2>Demande bilingue prête à relire</h2><p>EN ATTENTE DE VALIDATION HUMAINE. L'envoi reste votre décision ; aucune adresse déduite ni transmission automatique.</p>'''
for file,title in [('AUTHOR-REQUEST-FR.md','Français'),('AUTHOR-REQUEST-EN.md','English')]:s+='<details><summary>'+title+' — NON ENVOYÉ / NOT SENT</summary><pre>'+esc((D/file).read_text())+'</pre><a href="'+file+'">Télécharger le texte</a></details>'
s+='</section><section><h2>Six valeurs, pas une recette de scaling</h2><p>Valeurs VALIDÉES par provenance. Application : EN ATTENTE DE DOCUMENTATION. Aucun facteur appliqué.</p><div class="scroll"><table><tr><th>Nom</th><th>S01</th><th>Rôle documentaire</th></tr>'
for r in json.loads((D/'scaling-audit.json').read_text())['rows']:s+='<tr><td>'+r['name']+'</td><td>'+r['S01']+'</td><td>'+esc(r['documentedRole'])+'</td></tr>'
s+='''</table></div><p>Sans dimension. Ni l'ordre des axes du bassin, ni l'isotropie, ni les corps affectés ne sont déduits des noms. <a href="SCALING.md">Audit complet</a>.</p></section><section><h2>Solution indépendante : ce qui reste observable</h2><p>VALIDÉ pour la géométrie technique seulement : calcul du rang de pose rigide de groupes de landmarks et variations des distances sur rep1. Une ligne ne révèle pas sa rotation axiale ; une constellation non colinéaire peut donner un repère technique, pas un centre articulaire anatomique.</p><p>Aucune reconstruction anatomique produite. <a href="INDEPENDENT-PLAN.md">Plan, limites et calibration nouvelle</a> · <a href="observability.json">Résultats reproductibles</a>.</p></section><section><h2>Une seconde source précise, sans admission automatique</h2><p>WBDS — Fukuchi, Fukuchi et Duarte, Figshare5722711 <b>v6</b>. Licence du dataset CC BY4.0 vérifiée, protocole/supplément et modèleVisual3D consultés. <b>Marche, pas squat.</b> Archives de mouvements non acquises dans cette phase ; essai/statique et ambiguïtés de labels encore à qualifier.</p><p>EN ATTENTE DE VALIDATION HUMAINE. Aucun achatVisual3D, aucuneIK ni chaîne de retargeting. <a href="ALTERNATIVES.md">Comparaison et droits précis</a>.</p></section><section><h2>Paquet pour le professionnel</h2><p>Limites, matrice37×66, paramètresS01, forces3350samples/15répétitions, questions scientifiques et portes d'acceptation. <b>Dossier NON VALIDÉ et non transmis.</b></p><p><a href="PROFESSIONAL-REVIEW.md">Ouvrir le dossier de revue</a></p></section><section><h2>Documents et preuves</h2><ul>'''
for n,title in [('INVENTORY.md','Inventaire : URLs, versions, dates et portée'),('SCALING.md','Facteurs et lacunes'),('INDEPENDENT-PLAN.md','Plan indépendant et observabilité'),('ALTERNATIVES.md','Seconde source et conditions commerciales'),('PROFESSIONAL-REVIEW.md','Dossier professionnel'),('DECISION.md','Blocages et décision B'),('REPRODUCE.md','Reproduction et tests'),('decision.json','Statuts machine'),('manifest.json','Hashes du dossier'),('browser-report.json','Test de la page')]:s+='<li><a href="'+n+'">'+title+'</a></li>'
s+='''</ul></section><footer>Recherches documentaires et analysesPARISFIT, sans approbation des auteurs. Références et attributions dansINVENTORY.md. Rocketbox et les huit exercices préservés ; runtime inchangé. PR11 brouillon. Aucun envoi aux auteurs, achat, merge ou déploiement.</footer></main></html>'''
(D/'index.html').write_text(s)
files={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(D.iterdir()) if p.is_file() and p.name!='manifest.json'}
(D/'manifest.json').write_text(json.dumps({'status':'VALIDÉ','scope':'file integrity only; no scientific approval','files':files},indent=2)+'\n')
